<?php
require 'includes/auth_helpers.php'; require 'includes/db.php'; require_staff_or_admin($pdo); $uid=(int)$_SESSION['user_id']; $role=(string)$_SESSION['role'];
if($_SERVER['REQUEST_METHOD']==='POST' && !csrf_check($_POST['csrf']??null)){http_response_code(400);exit('Invalid request token.');}
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(isset($_POST['read_event']))$pdo->prepare('INSERT IGNORE INTO team_inbox_reads(event_id,user_id) VALUES(?,?)')->execute([(int)$_POST['read_event'],$uid]);
 if(isset($_POST['update_application'])){$id=(int)$_POST['application_id'];$st=$_POST['status'];$allowed=['new','reviewing','interview','offered','hired','rejected','withdrawn'];if(in_array($st,$allowed,true))$pdo->prepare('UPDATE careers_applications SET status=?,assigned_to=?,staff_notes=? WHERE application_id=?')->execute([ $st,($_POST['assigned_to']??'')!==''?(int)$_POST['assigned_to']:null,trim($_POST['staff_notes']??''),$id]);}
 if(isset($_POST['update_contact'])){$id=(int)$_POST['contact_id'];$st=$_POST['status'];if(in_array($st,['new','open','waiting','resolved','closed'],true))$pdo->prepare('UPDATE contact_submissions SET status=?,priority=?,assigned_to=?,staff_notes=? WHERE contact_id=?')->execute([$st,$_POST['priority']==='high'?'high':'normal',($_POST['assigned_to']??'')!==''?(int)$_POST['assigned_to']:null,trim($_POST['staff_notes']??''),$id]);}
 header('Location: team-inbox.php?tab='.rawurlencode($_POST['tab']??'activity'));exit;
}
$tab=$_GET['tab']??'activity';if(!in_array($tab,['activity','applications','feedback'],true))$tab='activity';
$staff=$pdo->query("SELECT c.user_id, i.first_name, i.last_name FROM user_credentials c JOIN user_info i ON i.user_id=c.user_id WHERE c.role IN ('staff','admin') AND c.is_active=1 ORDER BY i.first_name")->fetchAll();
$events=$pdo->prepare("SELECT e.*,r.read_at FROM team_inbox_events e LEFT JOIN team_inbox_reads r ON r.event_id=e.event_id AND r.user_id=? WHERE e.audience IN ('all',?, 'staff') ORDER BY e.created_at DESC LIMIT 150");$events->execute([$uid,$role]);$events=$events->fetchAll();
$applications=$pdo->query('SELECT * FROM careers_applications ORDER BY created_at DESC LIMIT 200')->fetchAll();$contacts=$pdo->query('SELECT * FROM contact_submissions ORDER BY created_at DESC LIMIT 200')->fetchAll();
$pageTitle='Team inbox';require 'includes/header.php'; ?>
<main class="container py-5"><div class="mb-4"><p class="text-uppercase small fw-semibold text-secondary mb-1">Team workspace</p><h1>Team inbox</h1><p class="text-secondary">Activity, career applications, and customer feedback in one place.</p></div><ul class="nav nav-pills mb-4"><li class="nav-item"><a class="nav-link <?=$tab==='activity'?'active':''?>" href="?tab=activity">Activity <span class="badge text-bg-light"><?=count($events)?></span></a></li><li class="nav-item"><a class="nav-link <?=$tab==='applications'?'active':''?>" href="?tab=applications">Applications <span class="badge text-bg-light"><?=count($applications)?></span></a></li><li class="nav-item"><a class="nav-link <?=$tab==='feedback'?'active':''?>" href="?tab=feedback">User feedback <span class="badge text-bg-light"><?=count($contacts)?></span></a></li></ul>
<?php if($tab==='activity'):?><div class="list-group inbox-list"><?php if(!$events):?><div class="form-panel text-center">No activity yet.</div><?php endif;?><?php foreach($events as $ev):?><article class="list-group-item d-flex justify-content-between align-items-start gap-3"><div><div class="d-flex gap-2 align-items-center"><span class="inbox-dot <?=$ev['read_at']?'read':''?>"></span><h2 class="h6 mb-1"><?=e($ev['title'])?></h2><span class="badge text-bg-light"><?=e(str_replace('_',' ',$ev['event_type']))?></span></div><p class="mb-1 text-secondary"><?=e($ev['message'])?></p><small class="text-secondary"><?=date('M j, Y g:i a',strtotime($ev['created_at']))?></small></div><?php if(!$ev['read_at']):?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="read_event" value="<?=(int)$ev['event_id']?>"><input type="hidden" name="tab" value="activity"><button class="btn btn-sm btn-outline-secondary">Mark read</button></form><?php endif;?></article><?php endforeach;?></div>
<?php elseif($tab==='applications'):?><div class="table-responsive form-panel p-0"><table class="table align-middle mb-0"><thead><tr><th>Applicant</th><th>Position</th><th>Received</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($applications as $a):?><tr><td><?=e($a['first_name'].' '.$a['last_name'])?><div class="small text-secondary"><?=e($a['email'])?></div></td><td><?=e($a['position_applied'])?></td><td><?=date('M j, Y',strtotime($a['created_at']))?></td><td><span class="badge text-bg-light"><?=e($a['status'])?></span></td><td><button class="btn btn-sm btn-outline-secondary" data-bs-toggle="modal" data-bs-target="#app<?=$a['application_id']?>">Review</button></td></tr><?php endforeach;?><?php if(!$applications):?><tr><td colspan="5" class="text-center py-5 text-secondary">No applications yet.</td></tr><?php endif;?></tbody></table></div>
<?php foreach($applications as $a):?><div class="modal fade" id="app<?=$a['application_id']?>" tabindex="-1"><div class="modal-dialog modal-lg modal-dialog-scrollable"><div class="modal-content order-options-modal"><form method="post"><div class="modal-header"><h2 class="modal-title h5">Application: <?=e($a['first_name'].' '.$a['last_name'])?></h2><button class="btn-close" data-bs-dismiss="modal" type="button"></button></div><div class="modal-body"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="update_application" value="1"><input type="hidden" name="application_id" value="<?=(int)$a['application_id']?>"><input type="hidden" name="tab" value="applications"><p><strong><?=e($a['position_applied'])?></strong> · <?=e($a['purpose'])?></p><p><?=e($a['email'])?> · <?=e($a['mobile_number'])?></p><p><?=e($a['address'])?></p><?php if($a['resume_path']):?><p><a href="resume-download.php?id=<?=(int)$a['application_id']?>">Download resume</a></p><?php endif;?><div class="mb-3"><label class="form-label">Status</label><select class="form-select" name="status"><?php foreach(['new','reviewing','interview','offered','hired','rejected','withdrawn'] as $s):?><option <?=$a['status']===$s?'selected':''?>><?=$s?></option><?php endforeach;?></select></div><div class="mb-3"><label class="form-label">Assigned to</label><select class="form-select" name="assigned_to"><option value="">Unassigned</option><?php foreach($staff as $s):?><option value="<?=(int)$s['user_id']?>" <?=$a['assigned_to']==$s['user_id']?'selected':''?>><?=e($s['first_name'].' '.$s['last_name'])?></option><?php endforeach;?></select></div><label class="form-label">Private team notes</label><textarea class="form-control" rows="3" name="staff_notes"><?=e($a['staff_notes'])?></textarea></div><div class="modal-footer"><button class="btn btn-order">Save review</button></div></form></div></div></div><?php endforeach;?>
<?php else:?><div class="table-responsive form-panel p-0"><table class="table align-middle mb-0"><thead><tr><th>Customer</th><th>Subject</th><th>Received</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($contacts as $c):?><tr><td><?=e($c['full_name'])?><div class="small text-secondary"><?=e($c['email'])?></div></td><td><?=e($c['subject'])?> <?=$c['priority']==='high'?'<span class="badge text-bg-danger">High</span>':''?></td><td><?=date('M j, Y',strtotime($c['created_at']))?></td><td><span class="badge text-bg-light"><?=e($c['status'])?></span></td><td><button class="btn btn-sm btn-outline-secondary" data-bs-toggle="modal" data-bs-target="#contact<?=$c['contact_id']?>">Open</button></td></tr><?php endforeach;?><?php if(!$contacts):?><tr><td colspan="5" class="text-center py-5 text-secondary">No feedback yet.</td></tr><?php endif;?></tbody></table></div>
<?php foreach($contacts as $c):?><div class="modal fade" id="contact<?=$c['contact_id']?>" tabindex="-1"><div class="modal-dialog modal-lg modal-dialog-scrollable"><div class="modal-content order-options-modal"><form method="post"><div class="modal-header"><h2 class="modal-title h5">Feedback from <?=e($c['full_name'])?></h2><button class="btn-close" data-bs-dismiss="modal" type="button"></button></div><div class="modal-body"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="update_contact" value="1"><input type="hidden" name="contact_id" value="<?=(int)$c['contact_id']?>"><input type="hidden" name="tab" value="feedback"><p><strong><?=e($c['subject'])?></strong></p><p><?=nl2br(e($c['message']))?></p><p><?=e($c['email'])?> · <?=e($c['mobile_number'])?></p><div class="row"><div class="col-md-6 mb-3"><label class="form-label">Status</label><select class="form-select" name="status"><?php foreach(['new','open','waiting','resolved','closed'] as $s):?><option <?=$c['status']===$s?'selected':''?>><?=$s?></option><?php endforeach;?></select></div><div class="col-md-6 mb-3"><label class="form-label">Priority</label><select class="form-select" name="priority"><option value="normal" <?=$c['priority']==='normal'?'selected':''?>>Normal</option><option value="high" <?=$c['priority']==='high'?'selected':''?>>High</option></select></div></div><div class="mb-3"><label class="form-label">Assigned to</label><select class="form-select" name="assigned_to"><option value="">Unassigned</option><?php foreach($staff as $s):?><option value="<?=(int)$s['user_id']?>" <?=$c['assigned_to']==$s['user_id']?'selected':''?>><?=e($s['first_name'].' '.$s['last_name'])?></option><?php endforeach;?></select></div><label class="form-label">Private team notes</label><textarea class="form-control" rows="3" name="staff_notes"><?=e($c['staff_notes'])?></textarea></div><div class="modal-footer"><button class="btn btn-order">Save update</button></div></form></div></div></div><?php endforeach;?><?php endif;?></main><?php require 'includes/footer.php'; ?>
